/**
 * A per-client bitfield, fixed at enrolment from `client_kind` and stored in
 * FRAM beside that client's counter. **P-105 in
 * [PROTOCOL.md](https://github.com/origin89hq/km43/blob/main/docs/PROTOCOL.md)
 * is the rule** — where the mask comes from, why `client_kind` is a sound input
 * where `transport` is not, that no message raises or lowers one, and what each
 * refusal is answered with. This file allocates the bits and the row each
 * `client_kind` is handed.
 */
export const ClientCapability = {
  /** The client may write configuration at all. */
  WRITE_CONFIG: 1 << 0,
  /**
   * The client may write the **network** (`0x0020`) and **cloud** (`0x0021`)
   * sections.
   */
  WRITE_NETWORK_AND_CLOUD: 1 << 1,
  /** The client may send `Command 0x08`. */
  SEND_COMMAND: 1 << 2,
  /** The client may set the clock with `Time 0x0A`. */
  SET_CLOCK: 1 << 3,
  /** The client may push firmware with `Firmware 0x09`. */
  PUSH_FIRMWARE: 1 << 4,
} as const;

