  AC_ENERGY_EXPORTED: 0x0207,
  /** Temperature. Unit `°C`, `value = raw × 10^-1`. */
  TEMPERATURE: 0x0302,
  /** Tank level. Unit `%`, `value = raw × 10^-1`. */
  TANK_LEVEL: 0x0401,
  /** Tank sender current. Unit `A`, `value = raw × 10^-6`. */
  TANK_SENDER_CURRENT: 0x0402,
  /** Generator state (enum, see below). No unit. */
