  /** Generator run hours. Unit `h`, `value = raw × 10^-2`. */
  GENERATOR_RUN_HOURS: 0x0502,
  /** Generator starts since commissioning. Unit `count`. */
  GENERATOR_STARTS_SINCE_COMMISSIONING: 0x0503,
  /** Run contact commanded (bool). No unit. */
  RUN_CONTACT_COMMANDED: 0x0504,
  /** Generator selector position (enum, see below). No unit. */
  GENERATOR_SELECTOR_POSITION: 0x0601,
  /** Uptime since boot. Unit `s`. */
