/**
 * The public equipment dataset's word for a reading: a metric kind over a
 * signal domain, at a place. An undefined place matches any; the domain never
 * does, so a limit or a period counter cannot borrow a live reading's word.
 */
export interface DatasetMetric {
  /** A {@link MetricKind} value. */
  readonly kind: number;
  /** A {@link SignalDomain} value, matched exactly. */
  readonly domain: number;
  /** A {@link ComponentRole} value, or undefined to match any role. */
  readonly role?: number;
  /** A {@link MeasurementPoint} value, or undefined to match any point. */
  readonly point?: number;
  /** The dataset's word, such as `pv-voltage`. */
  readonly name: string;
}

