/**
 * The dataset's word for a reading, or undefined when it has none. The first
 * matching row of {@link datasetMetrics} wins, which is why it is ordered most
 * specific first.
 */
export function datasetName(
  kind: number,
  domain: number,
  role?: number,
  point?: number,
): string | undefined {
  return datasetMetrics.find(
    (m) =>
      m.kind === kind &&
      m.domain === domain &&
      (m.role === undefined || m.role === role) &&
      (m.point === undefined || m.point === point),
  )?.name;
}
